  18     async execute(content: string, options: RagIndexingOptions): Promise<Result<RagIndexingResult, RagError>> {
  19         const result = await this.ragRepository.indexDocument(content, options);
  20         
  21         if (result.isSuccess) {
  22             const data = result.getValue();
  23             // Track the successful indexing
  24             await this.documentRepository.record({
  25                 projectId: options.projectId || 'unknown',
  26                 userId: options.userId,
  27                 sourceFile: options.sourceFile || 'unknown',
  28                 chunksCount: data.chunksCreated,
  29                 fileSize: content.length, // approximation
  30                 type: options.type ?? 'context',
  31                 chunkSize: options.chunkSize || 500,
  32                 overlap: options.overlap || 50,
  33             });
  34         } else {
  35             // Log failure to db as well
  36             await this.documentRepository.recordFailed({
  37                 projectId: options.projectId || 'unknown',
  38                 userId: options.userId,
  39                 sourceFile: options.sourceFile || 'unknown',
  40                 fileSize: content.length,
  41                 type: options.type ?? 'context',
  42                 errorMessage: result.error?.message || "Unknown indexing error",
