  10 export class SQLiteIndexedDocumentRepository implements IIndexedDocumentRepository {
  11     async record(data: Omit<IndexedDocumentRecord, 'id' | 'timestamp' | 'indexedAt' | 'status'>): Promise<Result<string, RagError>> {
  12         try {
  13             const id = uuidv4();
