  21                 indexedAt,
  22                 status: 'indexed',
  23             } as any);
  24             
  25             return Result.ok(id);
  26         } catch (error: any) {
  27             return Result.fail(RagError.internal(error.message));
  28         }
  29     }
  30 
  31     async recordFailed(data: Omit<IndexedDocumentRecord, 'id' | 'timestamp' | 'indexedAt' | 'status' | 'chunksCount'>): Promise<Result<string, RagError>> {
  32         try {
  33             const id = uuidv4();
  34             const now = Date.now();
  35             const indexedAt = new Date().toISOString();
  36             
  37             await db.insert(indexedDocuments).values({
  38                 ...data,
  39                 id,
