  53         try {
  54             const results = await db.query.indexedDocuments.findMany({
  55                 orderBy: [desc(indexedDocuments.indexedAt)],
  56                 limit,
  57             });
  58             return Result.ok(results.map(this.toDomain));
  59         } catch (error: any) {
  60             return Result.fail(RagError.internal(error.message));
  61         }
  62     }
