  92                 .where(eq(indexedDocuments.projectId, projectId));
  93             return Result.ok();
  94         } catch (error: any) {
  95             return Result.fail(RagError.internal(error.message));
  96         }
  97     }
  98 
  99     async deleteBySourceFile(sourceFile: string): Promise<Result<void, RagError>> {
 100         try {
 101             await db.update(indexedDocuments)
 102                 .set({ status: 'deleted' })
 103                 .where(eq(indexedDocuments.sourceFile, sourceFile));
 104             return Result.ok();
 105         } catch (error: any) {
 106             return Result.fail(RagError.internal(error.message));
 107         }
 108     }
 109 
 110     async search(query: string): Promise<Result<IndexedDocumentRecord[], RagError>> {
 111         try {
 112             const results = await db.query.indexedDocuments.findMany({
 113                 where: or(
 114                     like(indexedDocuments.sourceFile, `%${query}%`),
 115                     like(indexedDocuments.errorMessage, `%${query}%`)
 116                 ),
 117                 orderBy: [desc(indexedDocuments.indexedAt)],
 118             });
 119             return Result.ok(results.map(this.toDomain));
 120         } catch (error: any) {
 121             return Result.fail(RagError.internal(error.message));
 122         }
 123     }
 124 
 125     async getStats(): Promise<Result<{
 126         totalDocuments: number;
 127         totalChunks: number;
 128         projectCount: number;
 129         recentUploads: number;
 130     }, RagError>> {
 131         try {
 132             const [totalDocs] = await db.select({ value: count() }).from(indexedDocuments).where(eq(indexedDocuments.status, 'indexed'));
 133             const [totalChunks] = await db.select({ value: sql`SUM(${indexedDocuments.chunksCount})` }).from(indexedDocuments).where(eq(indexedDocuments.status, 'indexed'));
 134             const [projectCount] = await db.select({ value: sql`COUNT(DISTINCT ${indexedDocuments.projectId})` }).from(indexedDocuments).where(eq(indexedDocuments.status, 'indexed'));
 135             
 136             const oneDayAgo = Date.now() - 24 * 60 * 60 * 1000;
 137             const [recentUploads] = await db.select({ value: count() }).from(indexedDocuments).where(and(eq(indexedDocuments.status, 'indexed'), gte(indexedDocuments.timestamp, oneDayAgo)));
 138 
 139             return Result.ok({
 140                 totalDocuments: Number(totalDocs.value),
 141                 totalChunks: Number(totalChunks.value || 0),
 142                 projectCount: Number(projectCount.value || 0),
 143                 recentUploads: Number(recentUploads.value),
 144             });
 145         } catch (error: any) {
 146             return Result.fail(RagError.internal(error.message));
 147         }
 148     }
 149 
 150     private toDomain(result: any): IndexedDocumentRecord {
 151         return {
 152             ...result,
 153             indexedAt: result.indexedAt, // Drizzle returns strings/dates, Repository interface expected Timestamp (from firebase-admin)
 154         } as any;
 155     }
 156 }
 157 
 158 // Internal helper for gte since it's not imported above
 159 function gte(column: any, value: any) {
 160     return sql`${column} >= ${value}`;
 161 }
 162 
