   3 const CACHE_PREFIX = 'arkan-cache-';
   4 const CACHE_TTL_MS = 5 * 60 * 1000; // 5 minutes
   5 
   6 interface CacheEntry<T> {
   7   timestamp: number;
   8   data: T;
   9 }
  10 
  11 export function getFromCache<T>(key: string): T | null {
  12   if (typeof window === 'undefined') return null;
  13   const entry = localStorage.getItem(`${CACHE_PREFIX}${key}`);
  14   if (!entry) return null;
  15 
  16   try {
  17     const parsed: CacheEntry<T> = JSON.parse(entry);
  18     if (Date.now() - parsed.timestamp > CACHE_TTL_MS) {
  19       localStorage.removeItem(`${CACHE_PREFIX}${key}`);
  20       return null;
  21     }
  22     return parsed.data;
  23   } catch (error) {
  24     console.error('Failed to parse cache entry:', error);
  25     localStorage.removeItem(`${CACHE_PREFIX}${key}`);
  26     return null;
