  clientClass: ClientConstructor<TClient>,
  callback: (client: TClient, token: string) => Promise<Result<TValue, TError>>,
): Promise<TValue> => {
  const result = await runAuthenticatedClientCall(user, clientClass, callback);
  return unwrapResult(result);
};

